import { createPuzzlePDF } from './pdf.js';
import { generate, normalize } from './generator.js';
const main=document.querySelector('#main');
const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8H7.5A2.5 2.5 0 1 1 10 5.5L12 8Zm0 0h4.5A2.5 2.5 0 1 0 14 5.5L12 8Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',check:'m5 12 4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',pen:'m16 3 5 5L9 20l-6 1 1-6L16 3ZM13 6l5 5',printer:'M6 9V3h12v6M6 18H3v-8h18v8h-3M6 14h12v7H6z',cake:'M4 12h16v9H4zM4 15c2 3 4-3 6 0s4-3 6 0 4 0 4 0M8 12V8m4 4V8m4 4V8M8 5V3m4 2V3m4 2V3',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M18 8a4 4 0 0 1 0 8m4 5v-2a4 4 0 0 0-3-3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',grid:'M3 3h18v18H3zM3 9h18M3 15h18M9 3v18m6-18v18',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',back:'M19 12H5m5-5-5 5 5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',close:'m6 6 12 12M6 18 18 6',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 7M4 12l2 7a7 7 0 0 0 12-2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z'};
function icon(name){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.spark}"/></svg>`;}
function miniGrid(){const p=generate(example,{seed:9,attempts:5});return `<div class="mini-grid" style="grid-template-columns:repeat(${p.width},1fr)" aria-hidden="true">${p.grid.flatMap((row,r)=>row.map(cell=>`<span class="mini-cell ${!cell?'empty':''} ${cell?.letter&&r===Math.floor(p.height/2)?'accent':''}">${cell?.letter||''}</span>`)).join('')}</div>`;}
function home(){main.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('heart')} Vos souvenirs ont un nouveau terrain de jeu</div><h1>Vos histoires.<br>Vos mots.<br><em>Leur sourire.</em></h1><p>Un lieu, un surnom, un souvenir à deux…<br>Transformez ce qui vous lie en une grille de mots croisés qui ne ressemble qu’à vous.</p><div class="hero-actions"><a class="button" href="/creer">Créer ma grille ${icon('arrow')}</a><a class="button text" href="/creer?exemple=1">Voir un exemple <span aria-hidden="true">↗</span></a></div><div class="hero-note"><span>${icon('check')} Gratuit, sans compte</span><span>${icon('check')} Prêt à imprimer</span></div></div><div class="hero-art"><div class="sample-paper"><p class="paper-eyebrow">Une grille, mille souvenirs</p><h3>Nous, tout simplement.</h3><p class="paper-subtitle">Les petits détails de notre grande histoire.</p>${miniGrid()}<div class="paper-bottom">${[...'AMOUR'].map(c=>`<span>${c}</span>`).join('')}</div><p class="paper-footer">Créé avec ♡ · les mots à vous.</p></div><div class="floating-label one"><div class="float-icon">${icon('pen')}</div><div><strong>« Notre premier voyage ? »</strong><span>Vous seuls avez la réponse.</span></div></div><div class="floating-label two"><div class="float-icon">${icon('heart')}</div><div><strong>100 % votre histoire</strong><span>Le cadeau qui veut dire quelque chose.</span></div></div></div></section><section class="occasion-strip" id="occasions"><span>LES GRANDES OCCASIONS.<br>ET LES PETITS BONHEURS.</span><a href="/creer?occasion=anniversaire">${icon('cake')} Anniversaire</a><a href="/creer?occasion=couple">${icon('heart')} En amoureux</a><a href="/creer?occasion=mariage">${icon('spark')} Mariage</a><a href="/creer?occasion=famille">${icon('people')} En famille</a><a href="/creer?occasion=amitie">${icon('gift')} Juste comme ça</a></section><section class="section" id="comment"><div class="section-heading"><div class="eyebrow">Simple comme un souvenir</div><h2>Vous avez les mots.<br>On s’occupe de les croiser.</h2><p>Quelques minutes pour créer. Un vrai moment à partager.</p></div><div class="steps-cards">${[['heart','01','Choisissez votre occasion','Un anniversaire, un mariage ou simplement l’envie de faire sourire quelqu’un.'],['pen','02','Glissez-y votre histoire','Ajoutez vos mots et leurs indices. Nos questions vous aident à trouver l’inspiration.'],['printer','03','Imprimez. Offrez. Souriez.','Votre grille prend forme, avec son corrigé. Il ne manque plus qu’un crayon.']].map(([i,n,t,p])=>`<article class="how-card"><span class="number">${n}</span><div class="how-icon">${icon(i)}</div><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="story"><img src="/ambiance.jpg" alt="Deux personnes partagent un moment autour d’une grille de mots croisés et d’un café" loading="lazy" width="768" height="512"><div class="story-copy"><div class="eyebrow">Un peu de papier. Beaucoup de vous.</div><h2>Les meilleurs cadeaux<br>se vivent ensemble.</h2><p>Les blagues que personne d’autre ne comprend. Ce café où tout a commencé. Le surnom qui est resté. Faites-en un jeu, et laissez les souvenirs refaire surface.</p><a href="/creer" class="button secondary">À mon tour de créer ${icon('arrow')}</a></div></section><section class="section faq" id="questions"><div class="section-heading"><h2>Un dernier petit indice ?</h2></div><details><summary>Quelle différence entre mots croisés et mots fléchés ?</summary><p>Dans les mots croisés, les indices sont listés sous la grille. Dans les mots fléchés, ils sont placés directement dans les cases, avec une flèche qui indique le sens du mot. Les deux formats sont disponibles.</p></details><details><summary>Est-ce que je dois trouver tous les indices moi-même ?</summary><p>Vous pouvez écrire vos propres indices ou partir de nos questions adaptées à votre occasion. Ajoutez au moins 5 mots, jusqu’à 18, puis personnalisez chaque indice à votre guise.</p></details><details><summary>Comment récupérer ma grille en PDF ?</summary><p>Une fois votre grille générée, choisissez « Télécharger le PDF ». Votre fichier A4 est prêt à imprimer, avec le corrigé sur une page séparée si vous le souhaitez.</p></details><details><summary>Mes souvenirs restent-ils privés ?</summary><p>Vos mots sont traités dans votre navigateur. Votre brouillon est enregistré sur cet appareil uniquement, sans compte. Vous pouvez l’effacer depuis l’atelier de création.</p></details></section><section class="final-cta"><h2>Et si votre prochain cadeau tenait en quelques mots ?</h2><p>Les vôtres, surtout.</p><a href="/creer" class="button">Créer ma première grille ${icon('arrow')}</a></section>`;}
const occasions={anniversaire:{name:'Anniversaire',desc:'Une bougie de plus, mille souvenirs.',icon:'cake',title:'Une année de plus, tout un monde.',questions:['Son gâteau préféré','La ville où tout a commencé','Son surnom depuis toujours','Sa destination de rêve','Sa chanson préférée','Son petit plaisir du dimanche']},couple:{name:'En amoureux',desc:'Votre histoire, à deux.',icon:'heart',title:'Nous, tout simplement.',questions:['La ville de votre premier voyage','Votre petit surnom secret','Votre dessert à partager','Le lieu de votre première rencontre','Votre chanson à deux','Votre rituel du dimanche']},mariage:{name:'Mariage',desc:'Le grand oui et les petits détails.',icon:'spark',title:'Pour le meilleur et les souvenirs.',questions:['La ville de leur rencontre','Le lieu de la demande','Leur prochaine destination','Leur passion commune','Le prénom du témoin','Le dessert du grand jour']},famille:{name:'En famille',desc:'Les histoires qu’on aime se raconter.',icon:'people',title:'Notre joyeuse tribu.',questions:['Le plat de famille incontournable','Notre lieu de vacances préféré','Le prénom de notre grand-mère','Notre jeu du dimanche','Le nom de notre compagnon à quatre pattes','Notre tradition préférée']},amitie:{name:'Entre amis',desc:'Vos délires. Vos meilleurs souvenirs.',icon:'gift',title:'La bande, en quelques mots.',questions:['Notre ville de vacances préférée','Le surnom qui est resté','Notre rendez-vous du vendredi','Le prénom du plus grand bavard','Notre chanson culte','Notre passion commune']},libre:{name:'Juste pour le plaisir',desc:'Aucune occasion n’est trop petite.',icon:'pen',title:'Les petits bonheurs.',questions:['Un endroit qui vous fait sourire','Une passion à partager','Un souvenir en un mot','Un prénom qui compte','Un plaisir tout simple','Un mot qui vous ressemble']}};
const example=[{answer:'VENISE',clue:'Notre première escapade à deux'},{answer:'CHOCOLAT',clue:'Notre faiblesse après le dîner'},{answer:'PARIS',clue:'La ville de notre rencontre'},{answer:'SOLEIL',clue:'Ce qu’on cherche en vacances'},{answer:'CINEMA',clue:'Notre rendez-vous du vendredi'},{answer:'AMOUR',clue:'Le fil rouge de notre histoire'},{answer:'MUSIQUE',clue:'Elle accompagne nos trajets'},{answer:'CROISSANT',clue:'Le bonheur du dimanche matin'}];
const themes={rose:{label:'Framboise',accent:'#df315e',tint:'#fff0f3'},bleu:{label:'Océan',accent:'#35677c',tint:'#edf5f8'},vert:{label:'Forêt',accent:'#44705b',tint:'#eef5f0'},noir:{label:'Encre',accent:'#333333',tint:'#eeeeee'}};
const storageKey='les-mots-a-vous-v1';
let state={step:0,occasion:'',entries:[],title:'',signature:'',mystery:'',format:'croises',theme:'rose',includeSolution:true};
let puzzle=null,showSolution=false,editing=null,questionIndex=0,storageAvailable=true,generating=false,isExample=false;
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){if(isExample)return;try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{storageAvailable=false;}}
function restore(){try{const d=JSON.parse(localStorage.getItem(storageKey));if(!d||!Array.isArray(d.entries))return;state={...state,...d,entries:d.entries.slice(0,18).filter(e=>typeof e.answer==='string'&&typeof e.clue==='string').map(e=>({answer:normalize(e.answer).slice(0,18),clue:e.clue.slice(0,90)})),step:Math.min(Number(d.step)||0,2)};if(!occasions[state.occasion])state.occasion='';if(!themes[state.theme])state.theme='rose';if(!['croises','fleches'].includes(state.format))state.format='croises';if(state.step>0&&!state.occasion)state.step=0;if(state.step>1&&state.entries.length<5)state.step=1;state.title=String(state.title||'').slice(0,60);state.signature=String(state.signature||'').slice(0,50);state.mystery=normalize(state.mystery||'').slice(0,18);}catch{storageAvailable=false;}}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,4000);}
function heading(kicker,title,description){return `<div class="wizard-heading"><div class="eyebrow">${kicker}</div><h1 tabindex="-1">${title}</h1><p>${description}</p></div>`;}
function frame(content){main.innerHTML=`<div class="atelier"><div class="atelier-top"><a class="back-link" href="/">${icon('back')} Retour à l’accueil</a><ol class="stepper" aria-label="Étapes de création">${['L’occasion','Vos mots','La touche finale','Votre grille'].map((s,i)=>`<li class="${state.step===i?'active':state.step>i?'done':''}" ${state.step===i?'aria-current="step"':''}><span class="step-dot">${state.step>i?'✓':i+1}</span>${s}</li>`).join('')}</ol><span class="draft-status">${icon('lock')} ${isExample?'Exemple · non enregistré':storageAvailable?'Brouillon sur cet appareil':'Sauvegarde indisponible'}</span></div><div class="wizard ${state.step===3?'result-wizard':''}">${content}</div></div>`;}
function go(step){if(generating)return;state.step=step;editing=null;save();renderWizard();window.scrollTo({top:0,behavior:'instant'});main.querySelector('h1')?.focus({preventScroll:true});}
function selectOccasion(value){state.occasion=value;if(!state.title||Object.values(occasions).some(o=>o.title===state.title))state.title=occasions[value].title;questionIndex=0;go(1);}
function renderOccasion(){frame(heading('Tout commence par une attention','Pour quelle occasion ?','Choisissez votre point de départ. On vous aide à trouver les bons mots.')+`<div class="occasion-grid">${Object.entries(occasions).map(([key,o])=>`<button type="button" class="occasion-card ${state.occasion===key?'selected':''}" data-occasion="${key}">${icon(o.icon)}<span class="card-arrow" aria-hidden="true">↗</span><strong>${o.name}</strong><span>${o.desc}</span></button>`).join('')}</div><div class="wizard-footer"><span>Votre histoire reste sur cet appareil.</span><button type="button" class="button text" id="example">Essayer avec un exemple ${icon('arrow')}</button></div>`);main.querySelectorAll('[data-occasion]').forEach(b=>b.onclick=()=>selectOccasion(b.dataset.occasion));main.querySelector('#example').onclick=loadExample;}
function error(message){const el=main.querySelector('#form-error');if(el){el.textContent=message;el.hidden=false;}else toast(message);}
function renderWords(){
 const q=occasions[state.occasion].questions;
 const editingEntry=editing===null?null:state.entries[editing];
 const clueValue=editingEntry?.clue??q[questionIndex%q.length];
 frame(heading('Les mots qui vous ressemblent','Votre histoire, mot après mot.','Lisez ou écrivez un indice, puis ajoutez le mot qu’il fait deviner.')+`
 <div class="editor-layout"><section class="panel word-composer">
  <form id="word-form" novalidate>
   <div class="clue-heading"><label for="clue">Indice ${editing===null?state.entries.length+1:editing+1}</label><button type="button" id="edit-clue" class="icon-button" aria-label="Modifier l’indice">${icon('pen')}</button></div>
   <textarea id="clue" name="clue" class="clue-editor" rows="1" maxlength="90" placeholder="Écrivez votre indice…" aria-describedby="clue-help">${escape(clueValue)}</textarea>
   <p class="composer-help" id="clue-help">L’indice à lire pour trouver votre mot. Vous pouvez le modifier.</p>
   <div class="clue-options"><button type="button" id="next-question">${icon('refresh')} Un autre indice</button><button type="button" id="custom-clue">Écrire mon indice</button></div>
   <div class="answer-section"><label for="answer">Votre réponse, en un mot</label><input class="answer-input" id="answer" name="answer" type="text" maxlength="35" placeholder="Ex. : VENISE" autocomplete="off" spellcheck="false" value="${escape(editingEntry?.answer||'')}" aria-describedby="answer-help answer-count"><div class="answer-meta"><small id="answer-help">2 à 18 lettres, sans espaces ni accents dans la grille.</small><span id="answer-count">0 / 18</span></div></div>
   <figure class="live-word-preview" id="live-word-preview" hidden><figcaption>Votre indice prend vie</figcaption><div class="preview-scroll" tabindex="0" role="region" aria-label="Aperçu de l’indice suivi des lettres"><div class="letter-strip"><span class="preview-clue" id="preview-clue"></span><span class="preview-arrow" aria-hidden="true">${icon('arrow')}</span><div class="preview-letters" id="preview-letters" aria-hidden="true"></div></div></div></figure>
   <div id="form-error" class="field-error" role="alert" hidden></div><div class="form-actions"><button class="button" type="submit" ${state.entries.length>=18&&editing===null?'disabled':''}>${editingEntry?'Enregistrer le mot':'Ajouter ce mot'} ${icon(editingEntry?'check':'arrow')}</button>${editingEntry?'<button type="button" class="button secondary" id="cancel-edit">Annuler</button>':''}</div>
  </form>
 </section><section class="panel"><div class="panel-header"><h2>Vos mots à vous</h2><span class="counter">${state.entries.length} / 18</span></div>${state.entries.length?`<ol class="word-list">${state.entries.map((e,i)=>`<li class="word-row"><span class="word-number">${String(i+1).padStart(2,'0')}</span><div class="saved-pair"><p>${escape(e.clue)}</p><strong><span aria-hidden="true">→</span> ${escape(e.answer)}</strong></div><button class="icon-button" data-edit="${i}" aria-label="Modifier ${escape(e.answer)}">${icon('pen')}</button><button class="icon-button" data-remove="${i}" aria-label="Retirer ${escape(e.answer)}">${icon('close')}</button></li>`).join('')}</ol>`:`<div class="empty-words">${icon('grid')}<h3>Le premier souvenir est à vous.</h3><p>Un indice, sa réponse.<br>Votre histoire se construit ici.</p></div>`}<p class="word-help">${state.entries.length<5?`Encore ${5-state.entries.length} mot${5-state.entries.length>1?'s':''} pour créer votre grille.`:'✓ Vous avez assez de mots. Les autres, c’est du bonus.'}</p></section></div><div class="wizard-footer editor-bottom"><button class="button text" id="previous">${icon('back')} L’occasion</button><button class="button" id="continue" ${state.entries.length<5?'disabled':''}>La touche finale ${icon('arrow')}</button></div>`);
 const clueInput=main.querySelector('#clue'),answerInput=main.querySelector('#answer');
 const strip=main.querySelector('#preview-letters'),preview=main.querySelector('#live-word-preview');
 function updatePreview(animate=true){
  const answer=normalize(answerInput.value),letters=[...answer].slice(0,18);
  const clue=clueInput.value.trim();
  main.querySelector('#answer-count').textContent=`${answer.length} / 18`;
  main.querySelector('#answer-count').classList.toggle('over-limit',answer.length>18);
  main.querySelector('#preview-clue').textContent=clue||'Votre indice';
  preview.hidden=letters.length===0;
  preview.setAttribute('aria-label',`${clue||'Votre indice'} : ${answer}`);
  // Keep unchanged cells in place: only new or replaced letters animate.
  letters.forEach((letter,i)=>{
   const current=strip.children[i];if(current?.textContent===letter)return;
   const cell=document.createElement('span');cell.className='letter-tile'+(animate?' letter-enter':'');cell.textContent=letter;
   if(current)current.replaceWith(cell);else strip.append(cell);
  });
  while(strip.children.length>letters.length)strip.lastElementChild.remove();
  const scroller=main.querySelector('.preview-scroll');
  if(animate&&answerInput.selectionStart===answerInput.value.length)scroller.scrollLeft=scroller.scrollWidth;
 }
 function resizeClue(){clueInput.style.height='auto';clueInput.style.height=(clueInput.scrollHeight+2)+'px';}
 answerInput.addEventListener('input',()=>{updatePreview();main.querySelector('#form-error').hidden=true;});
 clueInput.addEventListener('input',()=>{resizeClue();updatePreview(false);main.querySelector('#form-error').hidden=true;});
 main.querySelector('#edit-clue').onclick=()=>{clueInput.focus();clueInput.select();};
 main.querySelector('#next-question').onclick=()=>{questionIndex++;clueInput.value=q[questionIndex%q.length];resizeClue();updatePreview(false);answerInput.focus();};
 main.querySelector('#custom-clue').onclick=()=>{clueInput.value='';resizeClue();updatePreview(false);clueInput.focus();};
 resizeClue();updatePreview(false);
 main.querySelector('#word-form').onsubmit=e=>{e.preventDefault();const raw=main.querySelector('#answer').value;if(/[^\p{L}\s'’-]/u.test(raw)){error('Utilisez uniquement des lettres, espaces, apostrophes ou tirets.');return;}const answer=normalize(raw),clue=main.querySelector('#clue').value.trim();if(answer.length<2||answer.length>18){error('Le mot doit contenir entre 2 et 18 lettres.');return;}if(!clue){error('Ajoutez un indice pour faire deviner ce mot.');return;}if(state.entries.some((e,i)=>e.answer===answer&&i!==editing)){error('Ce mot est déjà dans votre liste. Choisissez un autre souvenir.');return;}if(editing!==null)state.entries[editing]={answer,clue};else if(state.entries.length<18)state.entries.push({answer,clue});editing=null;questionIndex++;save();renderWords();main.querySelector('#answer').focus();};
 main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editing=Number(b.dataset.edit);renderWords();main.querySelector('#answer').focus();});main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.remove),entry=state.entries[i];state.entries.splice(i,1);editing=null;save();renderWords();toast(`${entry.answer} retiré de la liste.`);});main.querySelector('#cancel-edit')?.addEventListener('click',()=>{editing=null;renderWords();});main.querySelector('#previous').onclick=()=>go(0);main.querySelector('#continue').onclick=()=>go(2);
}
function renderFinalTouch(){frame(heading('Le petit détail qui change tout','La touche finale.','Un joli titre, votre style et peut-être une surprise cachée.')+`<div class="mystery-layout"><section class="panel"><h2>Personnalisez votre feuille</h2><label class="field"><span>Le titre de votre grille</span><input id="puzzle-title" type="text" maxlength="60" value="${escape(state.title)}" placeholder="Notre histoire, en quelques mots"></label><label class="field"><span>Votre signature <span class="optional">· facultatif</span></span><input id="signature" type="text" maxlength="50" value="${escape(state.signature)}" placeholder="Ex. : Avec amour, Camille"></label><div class="field"><span>Le format</span><div class="radio-options"><label class="radio-card"><input type="radio" name="format" value="croises" ${state.format==='croises'?'checked':''}>Mots croisés<small>Les indices sous la grille.</small></label><label class="radio-card"><input type="radio" name="format" value="fleches" ${state.format==='fleches'?'checked':''}>Mots fléchés<small>Les indices dans les cases.</small></label></div></div><div class="field"><span>La couleur de votre histoire</span><div class="color-options">${Object.entries(themes).map(([k,v])=>`<label class="color-choice" title="${v.label}" style="--color:${v.accent}"><input type="radio" name="theme" value="${k}" aria-label="${v.label}" ${state.theme===k?'checked':''}></label>`).join('')}</div></div></section><section class="panel"><div class="panel-header"><h2>Un mot mystère ?</h2><span class="optional">Facultatif</span></div><p class="mystery-explain">Des lettres à retrouver dans la grille pour révéler un dernier petit secret.</p><div class="mystery-tiles" id="mystery-preview">${mysteryTiles(state.mystery||'AMOUR',true)}</div><label class="field"><span>Votre mot secret</span><input id="mystery" class="answer-input" type="text" maxlength="30" value="${escape(state.mystery)}" placeholder="Ex. : AMOUR" aria-describedby="mystery-help"><small id="mystery-help">Jusqu’à 18 lettres. Elles doivent être présentes dans vos mots. Laissez vide pour passer.</small></label><div class="suggestions">${['AMOUR','MERCI','SURPRISE'].map(s=>`<button type="button" data-secret="${s}">${s}</button>`).join('')}</div><div id="form-error" role="alert" class="field-error" hidden></div></section></div><div class="wizard-footer editor-bottom"><button class="button text" id="previous">${icon('back')} Mes mots</button><button class="button" id="generate">Générer ma grille ${icon('spark')}</button></div>`);
 const update=()=>{state.title=main.querySelector('#puzzle-title').value;state.signature=main.querySelector('#signature').value;state.mystery=normalize(main.querySelector('#mystery').value);state.format=main.querySelector('[name=format]:checked').value;state.theme=main.querySelector('[name=theme]:checked').value;save();};main.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{update();if(el.id==='mystery')main.querySelector('#mystery-preview').innerHTML=mysteryTiles(state.mystery||'AMOUR',true);}));main.querySelectorAll('[data-secret]').forEach(b=>b.onclick=()=>{main.querySelector('#mystery').value=b.dataset.secret;update();main.querySelector('#mystery-preview').innerHTML=mysteryTiles(state.mystery,true);});main.querySelector('#previous').onclick=()=>{update();go(1);};main.querySelector('#generate').onclick=()=>{update();if(state.mystery.length>18){error('Le mot mystère est limité à 18 lettres.');return;}runGeneration();};
}
function mysteryTiles(word,show){return[...word].map((c,i)=>`<span class="mystery-tile"><sup>${i+1}</sup>${show?escape(c):''}</span>`).join('');}
async function runGeneration(){if(generating)return;generating=true;const old=puzzle;frame(`<div class="loading" role="status">${icon('spark')}<h2>Vos souvenirs se croisent…</h2><p>On cherche une belle place pour chacun de vos mots.</p></div>`);await new Promise(r=>setTimeout(r,60));try{const candidate=generate(state.entries,{format:state.format,mystery:state.mystery});if(candidate.unplaced.length)throw new Error('Ces mots n’ont pas trouvé de place : '+candidate.unplaced.map(w=>w.answer).join(', ')+'. Essayez des mots plus courts.');if(candidate.mystery.missing.length)throw new Error('Il manque ces lettres pour le mot mystère : '+candidate.mystery.missing.join(', ')+'. Modifiez le secret ou ajoutez des mots qui les contiennent.');puzzle=candidate;showSolution=false;state.step=3;save();renderResult();window.scrollTo({top:0,behavior:'instant'});}catch(e){puzzle=old;state.step=2;renderFinalTouch();error(e.message);}finally{generating=false;}}
function puzzleHTML(solution=false){const theme=themes[state.theme],m=puzzle.mystery;const selected=new Map(m.selected.map(c=>[`${c.row},${c.col}`,c.index]));return `<article class="puzzle-sheet ${state.format==='fleches'?'arrow-sheet':''}" style="--accent:${theme.accent};--tint:${theme.tint};--print-width:${Math.min(170,Math.round(135*puzzle.width/puzzle.height))}mm"><p class="sheet-eyebrow">${solution?'Le corrigé · ':''}Les mots à vous</p><h2>${escape(state.title.trim()||'Notre histoire, en quelques mots')}</h2><p class="sheet-subtitle">${solution?'Tous les souvenirs ont leur place.':'Les petits détails font les plus belles histoires.'}</p><div class="puzzle-grid" role="img" aria-label="Grille de ${puzzle.width} colonnes et ${puzzle.height} lignes${solution?', avec les réponses':''}" style="--cols:${puzzle.width}">${puzzle.grid.flatMap((row,r)=>row.map((cell,c)=>{if(!cell)return'<div class="puzzle-cell block"></div>';if(cell.clue){const word=puzzle.words.find(w=>w.id===cell.id);return`<div class="puzzle-cell clue-cell" title="${escape(cell.clue)}"><span class="clue-text">${escape(cell.clue)}</span><span class="clue-arrow">${word.number} ${cell.dir==='down'?'↓':'→'}</span></div>`;}const secret=selected.get(`${r},${c}`);return`<div class="puzzle-cell ${secret?'mystery-cell':''}">${cell.number?`<span class="cell-number">${cell.number}</span>`:''}${solution?cell.letter:''}${secret?`<span class="mystery-number">${secret}</span>`:''}</div>`;})).join('')}</div><div class="clue-columns">${['across','down'].map(dir=>`<div><h3>${dir==='across'?'Horizontalement →':'Verticalement ↓'}</h3>${puzzle.words.filter(w=>w.dir===dir).map(w=>`<p><b>${w.number}.</b> ${escape(w.clue)} ${solution?`<strong>(${w.answer})</strong>`:''}</p>`).join('')||'<p>—</p>'}</div>`).join('')}</div>${m.answer?`<p class="mystery-caption">Le mot mystère · Reportez les lettres des cases colorées numérotées.</p><div class="mystery-tiles">${mysteryTiles(m.answer,solution)}</div>`:''}${state.signature.trim()?`<p class="sheet-signature">${escape(state.signature)}</p>`:''}<p class="sheet-brand">Créé avec attention · les mots à vous.</p></article>`;}
function renderResult(){frame(heading('C’est vous, en quelques mots','Votre histoire a pris forme.','Une grille unique, prête à devenir un joli moment.')+`<div class="result-layout"><div><div class="result-toolbar"><div class="view-toggle" role="group" aria-label="Affichage de la grille"><button id="blank-view" aria-pressed="${!showSolution}">La grille</button><button id="solution-view" aria-pressed="${showSolution}">Le corrigé</button></div><button type="button" class="button secondary" id="regenerate">${icon('refresh')} Autre disposition</button></div>${state.format==='fleches'?'<p class="word-help">Sur petit écran, faites défiler la grille horizontalement. Les indices complets figurent aussi dessous.</p>':''}<div class="puzzle-scroll" id="puzzle-preview">${puzzleHTML(showSolution)}</div></div><aside class="result-aside"><section class="panel"><h2>Juste comme vous l’aimez.</h2><p>${state.entries.length} souvenirs, une seule grille. Vous pouvez encore changer un mot ou ajouter votre signature.</p><button class="button secondary" id="edit-words">${icon('pen')} Modifier mes mots</button><button class="button text" id="edit-style">Personnaliser la feuille</button><div class="result-stats"><span>${puzzle.words.length} mots</span><span>${puzzle.width} × ${puzzle.height} cases</span><span>${state.format==='fleches'?'Fléchés':'Croisés'}</span></div></section><section class="panel"><h2>Prête à offrir.</h2><p>Téléchargez votre création au format PDF, prête à imprimer ou à offrir.</p><label class="check-label"><input id="with-solution" type="checkbox" ${state.includeSolution?'checked':''}>Inclure le corrigé sur une page séparée</label><button class="button" id="pdf-download">${icon('download')} Télécharger le PDF</button><button class="button secondary" id="print">${icon('printer')} Imprimer</button><button class="button secondary" id="download">${icon('download')} Télécharger la grille (SVG)</button><p class="saved-note">Format A4 · Sans filigrane</p></section><button class="button text" id="mobile-edit">${icon('back')} Modifier ma création</button></aside></div><div class="wizard-footer editor-bottom"><a href="/" class="button text">${icon('back')} Retour à l’accueil</a><button class="button text" id="reset">${isExample?'Quitter l’exemple':'Effacer le brouillon'}</button></div>`);main.querySelector('#blank-view').onclick=()=>{showSolution=false;renderResult();};main.querySelector('#solution-view').onclick=()=>{showSolution=true;renderResult();};main.querySelector('#regenerate').onclick=runGeneration;main.querySelector('#edit-words').onclick=()=>go(1);main.querySelector('#edit-style').onclick=()=>go(2);main.querySelector('#mobile-edit').onclick=()=>go(2);main.querySelector('#with-solution').onchange=e=>{state.includeSolution=e.target.checked;save();};main.querySelector('#print').onclick=()=>{document.querySelector('#print-root').innerHTML=`<div class="print-page">${puzzleHTML(false)}</div>${state.includeSolution?`<div class="print-page">${puzzleHTML(true)}</div>`:''}`;window.print();};main.querySelector('#download').onclick=downloadSVG;main.querySelector('#pdf-download').onclick=()=>{try{createPuzzlePDF(window.jspdf.jsPDF,puzzle,state,themes[state.theme]).save('les-mots-a-vous.pdf');toast('Votre PDF est prêt.');}catch{toast('Le téléchargement a échoué. Vous pouvez utiliser Imprimer.');}};main.querySelector('#reset').onclick=()=>{if(isExample){location.href='/creer';return;}if(!confirm('Effacer le brouillon de cet appareil et commencer une nouvelle grille ?'))return;try{localStorage.removeItem(storageKey);}catch{}state={step:0,occasion:'',entries:[],title:'',signature:'',mystery:'',format:'croises',theme:'rose',includeSolution:true};puzzle=null;isExample=false;go(0);};}
function wrap(text,max=60){const lines=[];let line='';for(const w of text.split(/\s+/)){if((line+' '+w).length>max&&line){lines.push(line);line=w;}else line+=(line?' ':'')+w;}if(line)lines.push(line);return lines;}
function downloadSVG(){const cell=44,pad=45,w=Math.max(800,puzzle.width*cell+pad*2),x=(w-puzzle.width*cell)/2,y=145,theme=themes[state.theme];let content=`<rect width="100%" height="100%" fill="white"/><text x="${w/2}" y="42" text-anchor="middle" fill="${theme.accent}" font-size="13">LES MOTS À VOUS${showSolution?' · CORRIGÉ':''}</text><text x="${w/2}" y="86" text-anchor="middle" font-family="Georgia,serif" font-size="28">${escape(state.title||'Notre histoire')}</text>`;const selected=new Map(puzzle.mystery.selected.map(c=>[`${c.row},${c.col}`,c.index]));puzzle.grid.forEach((row,r)=>row.forEach((v,c)=>{const xx=x+c*cell,yy=y+r*cell,secret=selected.get(`${r},${c}`);content+=`<rect x="${xx}" y="${yy}" width="${cell}" height="${cell}" fill="${!v?'#e8e4e7':v.clue?'#f4f0f2':secret?theme.tint:'#fff'}" stroke="#aa9ca4" stroke-width=".6"/>`;if(v?.clue){const word=puzzle.words.find(word=>word.id===v.id);wrap(v.clue,10).slice(0,4).forEach((t,i)=>{content+=`<text x="${xx+3}" y="${yy+9+i*7}" font-size="6">${escape(t)}</text>`;});content+=`<text x="${xx+cell-3}" y="${yy+cell-3}" text-anchor="end" font-size="9">${word.number} ${v.dir==='down'?'↓':'→'}</text>`;}else if(v){if(v.number)content+=`<text x="${xx+3}" y="${yy+9}" font-size="7">${v.number}</text>`;if(showSolution)content+=`<text x="${xx+cell/2}" y="${yy+28}" text-anchor="middle" font-size="20">${v.letter}</text>`;if(secret)content+=`<text x="${xx+cell-3}" y="${yy+cell-3}" text-anchor="end" fill="${theme.accent}" font-size="8">${secret}</text>`;}}));let yy=y+puzzle.height*cell+38;for(const dir of ['across','down']){content+=`<text x="${pad}" y="${yy}" font-size="14" fill="${theme.accent}">${dir==='across'?'HORIZONTALEMENT':'VERTICALEMENT'}</text>`;yy+=25;for(const word of puzzle.words.filter(w=>w.dir===dir)){for(const line of wrap(`${word.number}. ${word.clue}${showSolution?' — '+word.answer:''}`,Math.floor((w-pad*2)/7))){content+=`<text x="${pad}" y="${yy}" font-size="13">${escape(line)}</text>`;yy+=20;}}yy+=16;}if(puzzle.mystery.answer){content+=`<text x="${pad}" y="${yy}" font-size="14">Mot mystère : ${showSolution?puzzle.mystery.answer:[...puzzle.mystery.answer].map((_,i)=>`[${i+1}]`).join(' ')}</text>`;yy+=35;}if(state.signature){content+=`<text x="${pad}" y="${yy}" font-size="13">${escape(state.signature)}</text>`;yy+=30;}const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${yy+20}" viewBox="0 0 ${w} ${yy+20}" font-family="Arial,sans-serif" fill="#252426">${content}</svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`les-mots-a-vous-${showSolution?'corrige':'grille'}.svg`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Votre fichier est téléchargé.');}
function renderWizard(){if(state.step===0)renderOccasion();else if(state.step===1)renderWords();else if(state.step===2)renderFinalTouch();else if(puzzle)renderResult();else{state.step=2;renderFinalTouch();}}
function loadExample(){isExample=true;state={...state,occasion:'couple',entries:example.map(e=>({...e})),title:occasions.couple.title,signature:'Avec amour, Camille',mystery:'AMOUR',step:2};save();runGeneration();}
function route(){if(location.pathname.replace(/\/$/,'')==='/creer'){restore();const params=new URLSearchParams(location.search);if(params.has('exemple'))loadExample();else if(occasions[params.get('occasion')])selectOccasion(params.get('occasion'));else renderWizard();}else home();}
route();
// Optional browser-native tools. The interface works without WebMCP support.
if(navigator.modelContext?.registerTool){
 const toolResult=data=>({content:[{type:'text',text:JSON.stringify(data)}]});
 try{
  navigator.modelContext.registerTool({name:'get_crossword_draft',description:'Lire le brouillon de mots croisés affiché dans cet atelier, avec ses mots, indices et préférences.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>toolResult({occasion:state.occasion,entries:state.entries,title:state.title,format:state.format,mystery:state.mystery,step:state.step})});
  navigator.modelContext.registerTool({name:'generate_crossword',description:'Générer localement la grille à partir du brouillon affiché. Nécessite 5 à 18 mots avec leurs indices. Ne transmet aucune donnée et ne télécharge aucun fichier.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>{if(location.pathname.replace(/\/$/,'')!=='/creer')return toolResult({error:'Ouvrez d’abord l’atelier de création.'});await runGeneration();return toolResult(state.step===3?{words:puzzle.words.length,width:puzzle.width,height:puzzle.height,format:state.format}:{error:main.querySelector('#form-error')?.textContent||'Vérifiez les mots et les indices.'});}});
 }catch{/* Browsers without the optional protocol keep the normal controls. */}
}

window.addEventListener('resize',()=>{const clue=main.querySelector('.clue-editor');if(clue){clue.style.height='auto';clue.style.height=(clue.scrollHeight+2)+'px';}});
